* { box-sizing: border-box; }
:root { color-scheme: dark; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; background: #172b35; color: #eff4e8; }
body { min-width: 360px; min-height: 100vh; margin: 0; display: grid; place-items: center; padding: 24px 16px; background-color: #172b35; background-image: linear-gradient(rgba(239,244,232,.035) 1px, transparent 1px), linear-gradient(90deg, rgba(239,244,232,.035) 1px, transparent 1px); background-size: 24px 24px; }
.meter-card { width: min(100%, 440px); padding: 30px; border: 2px solid #31515a; border-radius: 10px; background: #203942; box-shadow: 8px 8px 0 #101f27; }
.card-header { display: flex; align-items: center; gap: 15px; margin-bottom: 26px; }
.taxi-icon { width: 56px; height: 48px; display: grid; place-items: center; border: 2px solid #172b35; background: #f2c14e; color: #172b35; font-size: 15px; font-weight: 900; letter-spacing: 1px; box-shadow: 3px 3px 0 #172b35; }
.eyebrow, .stat-label { margin: 0; color: #9cb7ad; font-size: 13px; font-weight: 750; letter-spacing: 1.5px; }
h1 { margin: 4px 0 0; font-size: clamp(23px, 6vw, 29px); line-height: 1.15; letter-spacing: -.7px; }
.fare-panel { padding: 22px 24px 20px; border: 2px solid #31515a; border-radius: 6px; background: #172b35; }
.fare { margin: 5px 0 0; color: #f2c14e; font-size: clamp(50px, 14vw, 68px); font-weight: 800; line-height: 1.05; letter-spacing: -2px; font-variant-numeric: tabular-nums; }
.currency { margin-right: 3px; font-size: .55em; vertical-align: 10px; }
.fare-note { margin: 7px 0 0; color: #9cb7ad; font-size: 15px; }
.trip-stats { display: grid; grid-template-columns: 1fr 1fr; margin: 18px 0 24px; border: 2px solid #31515a; border-radius: 6px; }
.stat { display: flex; align-items: center; gap: 12px; min-width: 0; padding: 16px 13px; }
.stat + .stat { border-left: 2px solid #31515a; }
.stat-icon { width: 32px; height: 32px; display: grid; flex: 0 0 auto; place-items: center; border-radius: 5px; background: #31515a; color: #f2c14e; font-size: 24px; font-weight: 700; }
.clock-icon { font-size: 27px; }
.stat-value { margin: 3px 0 0; font-size: 22px; font-weight: 750; font-variant-numeric: tabular-nums; }
.unit { color: #9cb7ad; font-size: 15px; font-weight: 600; }
.controls { display: grid; gap: 10px; }
button { min-height: 54px; border: 2px solid #f2c14e; border-radius: 5px; font: inherit; font-size: 16px; font-weight: 750; cursor: pointer; transition: transform 100ms ease, background-color 100ms ease, box-shadow 100ms ease; }
.action-button { display: flex; align-items: center; gap: 12px; padding: 8px 14px; background: #f2c14e; color: #172b35; text-align: left; box-shadow: 0 3px 0 #b98c2d; }
.action-button:hover { background: #ffcf5c; }
.button-symbol { font-size: 23px; line-height: 1; }
.button-price { margin-left: auto; font-variant-numeric: tabular-nums; }
.reset-button { width: 100%; margin-top: 14px; border-color: #557078; background: transparent; color: #eff4e8; }
.reset-button span { margin-right: 7px; color: #f2c14e; font-size: 21px; vertical-align: -1px; }
.reset-button:hover { background: #31515a; }
button:focus-visible { outline: 3px solid #eff4e8; outline-offset: 3px; }
button:active { transform: translateY(2px); box-shadow: none; }
.card-footer { display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 22px; color: #9cb7ad; font-size: 12px; font-weight: 750; letter-spacing: 1px; }
.status-dot { width: 8px; height: 8px; border-radius: 50%; background: #8ed1a0; box-shadow: 0 0 8px rgba(142,209,160,.5); }
.footer-separator { color: #557078; }
@media (max-width: 390px) { .meter-card { padding: 23px 19px; } .stat { gap: 8px; padding: 13px 9px; } .stat-icon { width: 28px; height: 28px; } }

const fareOutput = document.getElementById('fare');
const distanceOutput = document.getElementById('distance');
const waitingOutput = document.getElementById('waiting');

let kilometers = 0;
let minutes = 0;

function updateMeter() {
  const fare = 3 + kilometers * 1.5 + minutes * 0.4;
  fareOutput.textContent = fare.toFixed(2);
  distanceOutput.textContent = kilometers;
  waitingOutput.textContent = minutes;
}

document.getElementById('add-km').addEventListener('click', () => {
  kilometers += 1;
  updateMeter();
});

document.getElementById('add-minute').addEventListener('click', () => {
  minutes += 1;
  updateMeter();
});

document.getElementById('new-trip').addEventListener('click', () => {
  kilometers = 0;
  minutes = 0;
  updateMeter();
});
